.chat-markdown-codeblock {
  backdrop-filter: blur(16px) !important;
  background: rgba(18, 10, 36, 0.75) !important;
  border: 1px solid rgba(255, 0, 127, 0.3) !important;
  box-shadow: 0 8px 32px rgba(255, 0, 127, 0.15) !important;
}
[data-chat-header] {
  backdrop-filter: blur(14px) !important;
  background: rgba(13, 7, 26, 0.8) !important;
  border-bottom: 1px solid rgba(255, 0, 127, 0.2) !important;
}
